import React, { useState } from 'react';
import api from '../api';

const AuthModal = ({ onAuthSuccess, showToast }) => {
    const [isRegister, setIsRegister] = useState(false);
    const [fullName, setFullName] = useState('');
    const [email, setEmail] = useState('client@ticketflow.ro');
    const [password, setPassword] = useState('password123');
    const [role, setRole] = useState('CLIENT');
    const [loading, setLoading] = useState(false);

    const quickFill = (demoEmail) => {
        setIsRegister(false);
        setEmail(demoEmail);
        setPassword('password123');
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        setLoading(true);
        try {
            const endpoint = isRegister ? '/auth/register' : '/auth/login';
            const payload = isRegister ? { fullName, email, password, role } : { email, password };
            const res = await api.post(endpoint, payload);
            localStorage.setItem('tf_token', res.data.token);
            localStorage.setItem('tf_user', JSON.stringify(res.data.user));
            onAuthSuccess(res.data.user);
            showToast(`Signed in as ${res.data.user.fullName} (${res.data.user.role})`, 'success');
        } catch (err) {
            showToast(err.response?.data?.message || 'Authentication failed', 'error');
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="min-h-screen flex items-center justify-center p-4 bg-slate-950">
            <div className="max-w-md w-full bg-slate-900 border border-slate-800 rounded-2xl p-6 sm:p-8 shadow-2xl space-y-6">
                <div className="flex items-center gap-3">
                    <div className="w-11 h-11 rounded-xl bg-gradient-to-br from-cyan-400 to-emerald-500 flex items-center justify-center font-extrabold text-slate-950 text-xl">
                        🎟️
                    </div>
                    <div>
                        <h1 className="text-xl font-extrabold text-white">TicketFlow <span className="text-xs font-mono px-2 py-0.5 rounded bg-cyan-500/15 text-cyan-400 border border-cyan-500/30">IoT EDGE v2.4</span></h1>
                        <p className="text-xs text-slate-400">Spring Security JWT &amp; RBAC Gateway</p>
                    </div>
                </div>

                {/* 1-Click Demo Credentials */}
                <div className="bg-slate-950 border border-slate-800 rounded-xl p-3 space-y-2">
                    <p className="text-[11px] font-mono uppercase tracking-wider text-slate-400">Quick-Fill Demo Accounts (pwd: password123)</p>
                    <div className="grid grid-cols-3 gap-1.5">
                        <button type="button" onClick={() => quickFill('client@ticketflow.ro')} className="py-1.5 px-2 rounded-lg bg-cyan-500/15 hover:bg-cyan-500/25 text-cyan-300 border border-cyan-500/30 text-xs font-semibold">
                            Client
                        </button>
                        <button type="button" onClick={() => quickFill('organizer@ticketflow.ro')} className="py-1.5 px-2 rounded-lg bg-indigo-500/15 hover:bg-indigo-500/25 text-indigo-300 border border-indigo-500/30 text-xs font-semibold">
                            Organizer
                        </button>
                        <button type="button" onClick={() => quickFill('admin@ticketflow.ro')} className="py-1.5 px-2 rounded-lg bg-amber-500/15 hover:bg-amber-500/25 text-amber-300 border border-amber-500/30 text-xs font-semibold">
                            Admin
                        </button>
                    </div>
                </div>

                <form onSubmit={handleSubmit} className="space-y-4">
                    {isRegister && (
                        <>
                            <div>
                                <label className="block text-xs font-semibold text-slate-300 mb-1">Full Name</label>
                                <input required type="text" value={fullName} onChange={(e) => setFullName(e.target.value)} placeholder="Alexandru Popescu" className="w-full px-3.5 py-2.5 rounded-xl bg-slate-950 border border-slate-700 text-sm text-white focus:outline-none focus:border-cyan-500" />
                            </div>
                            <div>
                                <label className="block text-xs font-semibold text-slate-300 mb-1">Account Role</label>
                                <select value={role} onChange={(e) => setRole(e.target.value)} className="w-full px-3.5 py-2.5 rounded-xl bg-slate-950 border border-slate-700 text-sm text-white focus:outline-none focus:border-cyan-500">
                                    <option value="CLIENT">CLIENT (Buy Tickets &amp; Wallet)</option>
                                    <option value="ORGANIZER">ORGANIZER (Create Events &amp; Analytics)</option>
                                </select>
                            </div>
                        </>
                    )}

                    <div>
                        <label className="block text-xs font-semibold text-slate-300 mb-1">Email Address</label>
                        <input required type="email" value={email} onChange={(e) => setEmail(e.target.value)} className="w-full px-3.5 py-2.5 rounded-xl bg-slate-950 border border-slate-700 text-sm text-white focus:outline-none focus:border-cyan-500" />
                    </div>

                    <div>
                        <label className="block text-xs font-semibold text-slate-300 mb-1">Password</label>
                        <input required type="password" value={password} onChange={(e) => setPassword(e.target.value)} className="w-full px-3.5 py-2.5 rounded-xl bg-slate-950 border border-slate-700 text-sm text-white focus:outline-none focus:border-cyan-500" />
                    </div>

                    <button disabled={loading} type="submit" className="w-full py-3 rounded-xl bg-gradient-to-r from-cyan-500 to-emerald-500 hover:from-cyan-400 hover:to-emerald-400 text-slate-950 font-bold text-sm shadow-lg shadow-cyan-500/20 transition">
                        {loading ? 'Authenticating...' : isRegister ? 'Create Account & Sign In' : 'Sign In to Platform'}
                    </button>
                </form>

                <div className="text-center pt-2 border-t border-slate-800">
                    <button type="button" onClick={() => setIsRegister(!isRegister)} className="text-xs text-cyan-400 hover:text-cyan-300 font-semibold">
                        {isRegister ? 'Already have an account? Sign In' : "Don't have an account? Register"}
                    </button>
                </div>
            </div>
        </div>
    );
};

export default AuthModal;
